#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
set +x
TOTAL_STAGES=5
local stack=/mnt/user/documents/compose/roundcube
local secrets=/mnt/cache/appdata/roundcube/secrets
local callback=https://mail.netbird.hjacke.com/index.php/login/oauth
local env_path="$secrets/.microsoft-oauth.env"
local app_url=https://entra.microsoft.com/
local tmp_id='' tmp_secret=''

if (( EUID != 0 )); then
  printf 'Run this script as root on tower. It writes protected server secrets.\n' >&2
  return 1
fi
if [[ ! -f "$stack/compose.yml" || ! -d "$secrets" ]]; then
  printf 'The Roundcube deployment is not present at the expected tower paths.\n' >&2
  return 1
fi
if [[ -L "$env_path" ]]; then
  printf 'Refusing to write through a symlink at the secret answer file.\n' >&2
  return 1
fi
umask 077
ENV_FILE="$env_path"
touch "$ENV_FILE"
chmod 0600 "$ENV_FILE"

banner 'Microsoft Outlook sign-in for private Roundcube'
note 'Do not enter your mailbox password into this terminal or into chat.'
note 'Only the Microsoft application secret belongs in the hidden prompt.'

stage 'Enable IMAP in Outlook.com'
open_url 'https://outlook.live.com/mail/0/options/mail/accounts'
step 'Sign in with the personal Microsoft account that owns your live.se mailbox.'
step 'Open Settings > Mail > Forwarding and IMAP.'
step 'Enable Let devices and apps use IMAP, then Save. POP can stay disabled.'
note 'Microsoft documents this at https://support.microsoft.com/en-us/outlook/pop-imap-and-smtp-settings-for-outlook-com'
confirm 'Have you enabled IMAP for the intended mailbox?' || return 1

stage 'Register your personal-account Web application'
open_url "$app_url"
step 'Use a Microsoft Entra directory where you are allowed to register applications.'
note 'Microsoft may require Azure account, subscription, tenant access, and application-registration permissions.'
note 'If you cannot access App registrations, stop here. This wizard does not create paid resources or tenants.'
step 'Open Entra ID > App registrations > New registration.'
step 'Name it Roundcube private mail. Choose Personal accounts only, also called Personal Microsoft accounts only.'
step 'Register the application, then open its Overview page.'
step 'Copy Application (client) ID. Do not copy Directory (tenant) ID or Object ID.'
ask MICROSOFT_CLIENT_ID 'Application (client) ID:'
while [[ ! "$MICROSOFT_CLIENT_ID" =~ ^[[:xdigit:]]{8}-[[:xdigit:]]{4}-[[:xdigit:]]{4}-[[:xdigit:]]{4}-[[:xdigit:]]{12}$ ]]; do
  warn 'The application ID must be a UUID.'
  ask MICROSOFT_CLIENT_ID 'Application (client) ID:'
done
write_env MICROSOFT_CLIENT_ID "$MICROSOFT_CLIENT_ID"

stage 'Add the private Web callback'
open_url "$app_url"
step 'In your application, open Authentication > Add a platform > Web, or Add redirect URI under Web.'
step "Add this exact URI, with no query string or extra trailing slash: $callback"
step 'Save the redirect URI. Keep public client flows and implicit grant options disabled.'
note 'This callback opens in your browser over NetBird. Microsoft does not need inbound access to Roundcube.'
note 'Roundcube requests delegated IMAP.AccessAsUser.All and SMTP.Send for https://outlook.office.com/.'
note 'It also requests openid, profile, email, and offline_access at first sign-in. These are not Graph Mail.Read/Mail.Send permissions.'
note 'If the portal requires explicit API permissions, use Office 365 Exchange Online delegated IMAP.AccessAsUser.All and SMTP.Send, not application permissions.'
confirm 'Is the exact HTTPS callback saved under the Web platform for this app?' || return 1

stage 'Create and capture the application secret'
open_url "$app_url"
step 'In the same application, open Certificates & secrets > Client secrets > New client secret.'
step 'Name it Roundcube private mail and choose an expiry you will rotate before. Record that expiry.'
step 'Copy the secret Value now. Do not copy Secret ID. This value may be shown only once.'
ask_secret MICROSOFT_CLIENT_SECRET 'Client secret Value, hidden input:'
while [[ -z "$MICROSOFT_CLIENT_SECRET" ]]; do
  warn 'The application secret cannot be empty.'
  ask_secret MICROSOFT_CLIENT_SECRET 'Client secret Value, hidden input:'
done
ask MICROSOFT_SECRET_EXPIRES 'Secret expiry date, YYYY-MM-DD:'
while [[ ! "$MICROSOFT_SECRET_EXPIRES" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; do
  ask MICROSOFT_SECRET_EXPIRES 'Secret expiry date, YYYY-MM-DD:'
done
write_env MICROSOFT_CLIENT_SECRET "$MICROSOFT_CLIENT_SECRET"
write_env MICROSOFT_SECRET_EXPIRES "$MICROSOFT_SECRET_EXPIRES"
note 'Answers are stored locally with mode 0600. The secret is never printed or put in Docker environment variables.'

stage 'Enable Microsoft sign-in and test your mailbox'
confirm 'Write these app credentials into the Roundcube secret files and enable Microsoft-only sign-in?' || return 1
for name in microsoft_client_id microsoft_client_secret; do
  if [[ -L "$secrets/$name" ]]; then
    printf 'Refusing to replace a secret symlink.\n' >&2
    return 1
  fi
done
tmp_id=$(mktemp "$secrets/.client-id.XXXXXX")
tmp_secret=$(mktemp "$secrets/.client-secret.XXXXXX")
printf '%s' "$MICROSOFT_CLIENT_ID" > "$tmp_id"
printf '%s' "$MICROSOFT_CLIENT_SECRET" > "$tmp_secret"
chown root:33 "$tmp_id" "$tmp_secret"
chmod 0640 "$tmp_id" "$tmp_secret"
mv -f "$tmp_id" "$secrets/microsoft_client_id"
mv -f "$tmp_secret" "$secrets/microsoft_client_secret"
unset MICROSOFT_CLIENT_SECRET
# PHP reads these files per request. No container restart or mailbox password is needed.
docker compose -f "$stack/compose.yml" config --quiet
open_url 'https://mail.netbird.hjacke.com/'
step 'Use a browser connected to NetBird. Sign in on Microsoft, complete MFA, and review the requested permissions.'
step 'Confirm that Roundcube loads the intended mailbox. Read an existing message, then send a test to an address you control.'
step 'Confirm receipt of the test. Check the From address if live.se is an alias of another primary Microsoft address.'
note 'The server deployment is ready, but successful registration alone does not prove inbox or SMTP access.'
note 'If access fails, check IMAP enablement, callback matching, personal-account audience, delegated scopes, and secret Value/expiry.'
note 'Do not disable Microsoft 365 tenant security defaults for a personal live.se account.'
if confirm 'Did both inbox access and the test send succeed?'; then
  write_env MICROSOFT_MAIL_TEST 'owner-confirmed-inbox-and-send'
else
  write_env MICROSOFT_MAIL_TEST 'not-yet-verified'
  SKIPPED+=('First inbox access and SMTP send are not yet verified. Do not paste tokens or secrets into chat.')
fi
finish
note 'App-secret expiry: '"$MICROSOFT_SECRET_EXPIRES"'. Rotate before that date by rerunning this wizard with the new secret.'
}

run_wizard "$@"; exit
